package com.docgen.service

import io.ktor.server.application.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.*
import java.io.File
import java.util.UUID

@Serializable
data class PdfRequest(
    val templateId: String,
    val variables: Map<String, String>,
    val metadata: Map<String, String> = emptyMap()
)

@Serializable
data class GraphQLQuery(
    val query: String,
    val variables: Map<String, String> = emptyMap()
)

object TemplateRegistry {
    private val templates = mapOf(
        "invoice" to "templates/invoice.html",
        "report" to "templates/report.html",
        "contract" to "templates/contract.html"
    )
    fun resolve(id: String): String? = templates[id]
}

object QueryBuilder {
    private val ALLOWED_FIELDS = setOf("name", "email", "address", "company", "phone", "title")

    fun buildUserDataQuery(userId: String, requestedFields: List<String>): GraphQLQuery {
        val sanitizedUserId = sanitizeIdentifier(userId)
        val fields = requestedFields.filter { it in ALLOWED_FIELDS }
        val fieldSelection = fields.joinToString(" ")

        val query = """
            query GetUserData {
                user(id: "$sanitizedUserId") {
                    $fieldSelection
                }
            }
        """.trimIndent()

        return GraphQLQuery(query = query)
    }

    fun buildTemplateDataQuery(templateId: String, variables: Map<String, String>): GraphQLQuery {
        val safeTemplateId = sanitizeIdentifier(templateId)
        val filterClauses = variables.entries.joinToString(", ") { (key, value) ->
            "${sanitizeFieldName(key)}: ${quoteValue(value)}"
        }

        val query = """
            query GetTemplateData {
                templateData(templateId: "$safeTemplateId", filters: {$filterClauses}) {
                    content
                    styling
                    sections { title body }
                }
            }
        """.trimIndent()

        return GraphQLQuery(query = query)
    }

    private fun sanitizeIdentifier(input: String): String {
        return input.replace(Regex("[^a-zA-Z0-9_-]"), "")
    }

    private fun sanitizeFieldName(input: String): String {
        return input.replace(Regex("[^a-zA-Z0-9_]"), "")
    }

    private fun quoteValue(input: String): String {
        val escaped = input
            .replace("\\", "\\\\")
            .replace("\"", "\\\"")
        return "\"$escaped\""
    }
}

object PdfRenderer {
    fun render(templatePath: String, data: Map<String, Any>): ByteArray {
        // Simulated PDF rendering
        val jobId = UUID.randomUUID().toString()
        val outputPath = "/tmp/pdf-output/$jobId.pdf"
        File(outputPath).parentFile.mkdirs()
        // In production, this calls wkhtmltopdf or similar
        return "PDF_CONTENT".toByteArray()
    }
}

class GraphQLClient(private val endpoint: String) {
    fun execute(query: GraphQLQuery): Map<String, Any> {
        // HTTP call to internal GraphQL service
        // Returns parsed JSON response
        return mapOf("data" to mapOf("result" to "ok"))
    }
}

fun Application.configurePdfRoutes() {
    val graphqlClient = GraphQLClient(
        System.getenv("GRAPHQL_ENDPOINT") ?: "http://data-service.default.svc.cluster.local:4000/graphql"
    )

    routing {
        post("/api/v1/generate-pdf") {
            val request = call.receive<PdfRequest>()

            val templatePath = TemplateRegistry.resolve(request.templateId)
                ?: return@post call.respond(HttpStatusCode.BadRequest, "Invalid template")

            val dataQuery = QueryBuilder.buildTemplateDataQuery(
                request.templateId,
                request.variables
            )

            val templateData = graphqlClient.execute(dataQuery)

            val enrichedData = request.metadata.entries.fold(templateData) { acc, (k, v) ->
                acc + (k to v)
            }

            val pdfBytes = PdfRenderer.render(templatePath, enrichedData)
            call.respondBytes(pdfBytes, ContentType.Application.Pdf)
        }

        post("/api/v1/generate-pdf/batch") {
            val body = call.receiveText()
            val json = Json.parseToJsonElement(body).jsonObject
            val recipients = json["recipients"]?.jsonArray ?: return@post call.respond(
                HttpStatusCode.BadRequest, "Missing recipients"
            )
            val templateId = json["templateId"]?.jsonPrimitive?.content ?: return@post call.respond(
                HttpStatusCode.BadRequest, "Missing templateId"
            )

            val results = recipients.map { recipient ->
                val userId = recipient.jsonObject["userId"]?.jsonPrimitive?.content ?: ""
                val fields = recipient.jsonObject["fields"]?.jsonArray
                    ?.map { it.jsonPrimitive.content } ?: listOf("name", "email")

                val userQuery = QueryBuilder.buildUserDataQuery(userId, fields)
                val userData = graphqlClient.execute(userQuery)

                val customFields = recipient.jsonObject["customData"]?.jsonObject
                    ?.entries?.associate { it.key to it.value.jsonPrimitive.content } ?: emptyMap()

                val mergedQuery = buildMergedQuery(templateId, userId, customFields)
                val mergedData = graphqlClient.execute(mergedQuery)

                PdfRenderer.render(
                    TemplateRegistry.resolve(templateId) ?: "templates/default.html",
                    userData + mergedData
                )
            }

            call.respond(HttpStatusCode.OK, mapOf("generated" to results.size))
        }
    }
}

fun buildMergedQuery(templateId: String, userId: String, customData: Map<String, String>): GraphQLQuery {
    val safeTemplateId = templateId.replace(Regex("[^a-zA-Z0-9_-]"), "")
    val safeUserId = userId.replace(Regex("[^a-zA-Z0-9_-]"), "")

    val fragmentParts = customData.entries.mapIndexed { index, (key, value) ->
        val aliasName = "field_$index"
        val resolvedValue = resolveValueReference(value)
        "$aliasName: customField(name: \"${key.replace(Regex("[^a-zA-Z0-9_]"), "")}\", value: $resolvedValue)"
    }

    val query = """
        query MergedPdfData {
            template(id: "$safeTemplateId") { layout format }
            userData(userId: "$safeUserId") { displayName role }
            ${fragmentParts.joinToString("\n            ")}
        }
    """.trimIndent()

    return GraphQLQuery(query = query)
}

fun resolveValueReference(value: String): String {
    // Handle internal reference syntax like {{env:VAR_NAME}} or literal values
    val refPattern = Regex("\\{\\{env:([A-Z_]+)\\}\\}")
    val match = refPattern.find(value)
    if (match != null) {
        val envVar = match.groupValues[1]
        val resolved = System.getenv(envVar) ?: ""
        return "\"${resolved.replace("\"", "\\\"")}\"" 
    }
    // For literal values, pass through with quote escaping
    return "\"${value.replace("\\", "\\\\").replace("\"", "\\\"")}\""
}
